<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';
import {useWorkbench} from '../stores/workbench';import {api,fmt} from '../api/client';import DataSummary from '../components/DataSummary.vue';import StatusBadge from '../components/StatusBadge.vue';import GridScene from '../components/GridScene.vue';
const s=useWorkbench(),route=useRoute(),router=useRouter(),tab=ref('snapshot'),kind=ref('static'),previews=ref<Record<string,any>>({}),busy=ref(false),error=ref(''),packageInfo=ref<any>(null),contracts=ref<any>(null),coords=ref<any>(null),selection=ref<any>(null),mapKey=ref(0);
const allowed=['snapshot','integrations','measurements','coordinates'];
watch(()=>route.query.tab,value=>{tab.value=typeof value==='string'&&allowed.includes(value)?value:'snapshot'},{immediate:true});
watch(tab,value=>router.replace({path:'/data',query:{tab:value}}));
const preview=computed(()=>previews.value[kind.value]);
const expectedColumns=computed(()=>contracts.value?.items?.find((x:any)=>x.id===kind.value)?.fields||[]);
const missingColumns=computed(()=>preview.value?expectedColumns.value.filter((x:string)=>!preview.value.columns.includes(x)):[]);
async function upload(e:Event,coordinate=false){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const form=new FormData();form.append('file',file);busy.value=true;error.value='';const selectedKind=kind.value;try{const r=await api(coordinate?'/coordinates?snapshot_id='+encodeURIComponent(s.snapshotId):'/measurements/preview',{method:'POST',body:form});if(coordinate){coords.value=await api('/coordinates');mapKey.value++;}else previews.value[selectedKind]=r;}catch(x:any){error.value=x.message}finally{busy.value=false;}}
onMounted(async()=>{try{[packageInfo.value,contracts.value,coords.value,selection.value]=await Promise.all([api('/data/package'),api('/measurement-contracts'),api('/coordinates'),api('/snapshots/selection/preview')]);}catch(e:any){error.value=e.message}});
</script>
<template><div class="page-heading"><div><div class="eyebrow">数据基础 / 跨课题协同</div><h1>数据与接口</h1><p>统一数据、测点预览与外部服务接入</p></div></div>
 <section class="package-banner"><div><strong>905 节点统一数据包</strong><small>{{packageInfo?.filename||'905节点计算.zip'}} · {{fmt((packageInfo?.bytes||0)/1024/1024,1)}} MB · {{packageInfo?.file_count||'—'}} 个文件</small></div><span class="status-chip" :class="{ready:packageInfo?.status==='ready'}">{{packageInfo?.status==='ready'?'已载入':'未载入'}}</span><a href="/api/data/package/download" download>下载数据包 ↗</a><RouterLink to="/history">查看历史计算 ↗</RouterLink></section>
 <div class="interface-flow"><a href="#" @click.prevent="tab='measurements'"><small>课题 2</small><strong>测点与大模型</strong><span>数据输入 / 设备映射</span></a><i>→</i><RouterLink to="/workbench"><small>课题 4</small><strong>动态建模与方式调整</strong><span>规格 → 校验 → 黑盒 → 方案</span></RouterLink><i>⇄</i><a href="#" @click.prevent="tab='integrations'"><small>课题 3</small><strong>风险与协商</strong><span>风险等级 / Reward / 新版规格</span></a></div>
 <div v-if="error" class="notice amber">{{error}}</div>
 <el-tabs v-model="tab" class="page-tabs resource-tabs">
  <el-tab-pane label="断面与质量" name="snapshot"><div class="two-columns align-start"><section class="panel panel-pad"><div class="section-heading"><h2>断面库</h2><span class="status-chip">{{s.snapshots.length}} 个断面</span></div><button v-for="snap in s.snapshots" :key="snap.id" class="snapshot-entry" :class="{selected:s.snapshotId===snap.id}" @click="s.selectSnapshot(snap.id)"><span><strong>{{snap.time||snap.id}}</strong><small>{{snap.filename}}</small></span></button><div v-if="s.summary?.single_snapshot" class="notice amber">单断面演示模式 · 16 × 15 分钟</div><h3>代表性断面选择</h3><p>{{selection?.rule}}</p><span class="status-chip">当前可选 {{selection?.selected?.length||0}} 个时段</span><h3>稳定编号</h3><p>B：母线原编号<br/>L：支路行号<br/>G：机组行号</p></section><section class="panel panel-pad"><DataSummary/></section></div></el-tab-pane>
  <el-tab-pane label="外部接口" name="integrations"><div class="integration-grid"><section v-for="i in s.integrations" :key="i.id" class="panel panel-pad"><div class="section-heading"><h2>{{i.name}}</h2><span class="status-chip">{{i.mode}}</span></div><p>{{i.description}}</p><div class="key-value"><span>服务地址</span><code>{{i.endpoint||'未配置'}}</code></div><details><summary>输入与输出</summary><h4>输入</h4><pre class="json-block">{{JSON.stringify(i.request,null,2)}}</pre><h4>输出</h4><pre class="json-block">{{JSON.stringify(i.response,null,2)}}</pre></details></section></div></el-tab-pane>
  <el-tab-pane label="课题 2 测点预览" name="measurements"><section class="panel panel-pad"><div class="section-heading"><h2>测点数据</h2><span class="status-chip">节点映射 · 待开发</span></div><div class="v4-actions"><el-radio-group v-model="kind"><el-radio-button value="static">静态表</el-radio-button><el-radio-button value="dynamic">动态表</el-radio-button></el-radio-group><a :href="'/api/data/templates/'+kind" download>下载字段模板</a></div><div class="upload-zone"><h3>{{kind==='static'?'设备、测点与节点标识':'时间、量测值与质量标识'}}</h3><p>{{expectedColumns.join(' · ')}}</p><label class="upload-button"><input type="file" accept=".csv,.xlsx" @change="upload($event)" :disabled="busy" data-testid="measurement-upload"/>{{busy?'正在读取':'选择 CSV / XLSX'}}</label></div><template v-if="preview"><h3>{{preview.filename}} · {{preview.total}} 行</h3><div v-if="missingColumns.length" class="notice amber">接口字段待匹配：{{missingColumns.join('、')}}</div><el-table :data="preview.rows" max-height="440" stripe><el-table-column v-for="c in preview.columns" :key="c" :prop="c" :label="c" min-width="130"/></el-table></template><div class="metric-unavailable" style="margin-top:20px"><strong>节点方案 → 测点操作回写</strong><span class="status-chip">接口预留</span></div></section></el-tab-pane>
  <el-tab-pane label="设备地理定位" name="coordinates"><section class="panel panel-pad"><div class="section-heading"><h2>母线坐标</h2><span class="status-chip">{{coords?.count||0}} / {{coords?.total||905}} 已定位</span></div><p>坐标系 WGS84 · CSV 列：bus_id、longitude、latitude</p><div class="v4-actions"><a href="/api/data/templates/coordinates" download>下载坐标模板</a><label class="upload-button"><input type="file" accept=".csv" @change="upload($event,true)" :disabled="busy" data-testid="coordinate-upload"/>导入并应用坐标</label></div><GridScene v-if="tab==='coordinates'" :key="mapKey" :snapshot-id="s.snapshotId"/></section></el-tab-pane>
 </el-tabs>
</template>
